    "id": "D71-190",
    "title": "The least universal size of a Condorcet-winning set",
    "jel_code": "D71",
    "domain_label": "Game theory",
    "status": "open",
    "llm_status": "unresolved",
    "rank": 190,
    "source_id": "OP-0203",
